<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'CSP Hash Generator','description'=>'Generate a SHA-256 base64 hash for inline script or style content locally.','url'=>'https://smarttoolz.in/tools/csp-hash-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>CSP Hash Generator</h1><p>Generate a SHA-256 hash suitable for a Content Security Policy hash source.</p><textarea id="i" placeholder="Paste inline script or style content"></textarea><button id="go">Generate CSP Hash</button><div id="o"></div></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool textarea{width:100%;min-height:180px;box-sizing:border-box;padding:14px;border:1px solid #ddd;border-radius:12px}.tool button{margin-top:12px;padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}.tool #o{margin-top:16px;padding:14px;background:#f6f7fb;border-radius:10px;word-break:break-all;font-family:monospace}</style><script>go.onclick=async()=>{const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(i.value));o.textContent="'sha256-"+btoa(String.fromCharCode(...new Uint8Array(h)))+"'"}</script><?php smarttoolz_tool_page_end(); ?>